TITLE='זכויות האדם לפני המהפכה החוקתית'
SUM=[
h3('8.1 המצב עד 1992: זכויות ללא עיגון חוקתי'),
p('עד חקיקת חוקי היסוד של 1992 לא היה לזכויות האדם בישראל עיגון חוקתי מפורש. הכנסת הייתה ריבונית, ויכלה, מבחינה פורמלית, לחוקק חוק הפוגע בכל זכות, ולבית המשפט לא הייתה סמכות לפסול אותו. ועם זאת, זכויות האדם הוכרו והוגנו הלכה למעשה, בעיקר דרך הפסיקה. הבנת השיטה שלפני 1992 חשובה משום שהיא מסבירה מה בדיוק שינתה "המהפכה החוקתית": לא את עצם קיומן של זכויות, אלא את מעמדן הנורמטיבי ואת סמכות בית המשפט להגן עליהן מפני חקיקה.'),
h3('8.2 שלושה מקורות להכרה בזכויות'),
ol('<b>מגילת העצמאות</b> - הכריזה על שוויון זכויות חברתי ומדיני גמור, על חופש דת, מצפון, לשון, חינוך ותרבות. אין לה מעמד חוקתי מחייב כשלעצמה, אך היא משמשת כלי פרשני ומקור השראה לעקרונות היסוד של השיטה.','<b>חקיקה רגילה</b> - חוקים שהגנו על זכויות מסוימות, כמו חוק שוויון זכויות האישה (1951), חוק הגנת הפרטיות (1981) וחוק איסור לשון הרע.','<b>הפסיקה</b> - "מגילת זכויות שיפוטית": בית המשפט העליון הכיר בזכויות יסוד רבות כעקרונות יסוד של השיטה, אף שלא היו כתובות בחוק.'),
box('case','קול העם (בג"ץ 73/53, 1953)','שר הפנים סגר שני עיתונים (קול העם ואל-אתיחאד) בטענה שהם מסכנים את שלום הציבור. בית המשפט, מפי השופט אגרנט, ביטל את הסגירה: חופש הביטוי הוא יסוד המשטר הדמוקרטי, וסמכות השר תיפרש בצמצום. נקבע מבחן <b>הוודאות הקרובה</b>: אפשר להגביל ביטוי רק כשיש ודאות קרובה לפגיעה ממשית בשלום הציבור. ההלכה ניתנה לפני כל עיגון חוקתי, והיא דוגמה מובהקת להגנה פרשנית.'),
h3('8.3 הכוח והמגבלה של ההגנה השיפוטית'),
p('מה יכלה הפסיקה לעשות? היא פירשה חוקים כך שיקיימו זכויות, לפי <b>חזקה פרשנית</b> שהמחוקק לא התכוון לפגוע בזכות יסוד אלא אם אמר זאת במפורש. היא ריסנה את הרשות המבצעת באמצעות עקרון חוקיות המנהל, כללי הצדק הטבעי והסבירות. ומה לא יכלה? לפסול חוק מפורש של הכנסת. כשהמחוקק אמר במפורש שהוא פוגע בזכות, לא עמד לבית המשפט כלי לביטול. לכן ההגנה הייתה חלשה מול חקיקה מפורשת, בשונה ממצב אחרי 1992.'),
tbl(['','לפני 1992','אחרי 1992 ו-1995'],[
['מעמד הזכויות','עקרונות יסוד שיפוטיים','זכויות חוקתיות מנויות ובלתי מנויות'],
['פגיעה בחוק מפורש','תקפה','תקפה רק אם עמדה בפסקת ההגבלה'],
['סמכות בג"ץ','פרשנות וביקורת מנהלית','גם פסילת חוק רגיל'],
['נטל ההצדקה','לרוב על הפרט','על הרשות הפוגעת']]),
h3('8.4 דוגמאות לפסיקה מוקדמת'),
box('case','ברגמן נ׳ שר האוצר (1969)','חוק מימון מפלגות העדיף מפלגות קיימות ונחקק ללא הרוב המשוריין. בית המשפט קבע שאינו תקף. ההלכה: שוויון בבחירות הוא עקרון יסוד, והכנסת כבולה בהוראת שריון. זה ביטוי מוקדם להגנה על שוויון, אך מכוח שריון פורמלי ולא מכוח זכות חוקתית כללית.'),
box('case','שניצר נ׳ הצנזור הצבאי הראשי (בג"ץ 680/88, 1989)','הצנזור פסל פרסום של מאמר עיתונאי בנושא ביטחוני. בית המשפט קבע שגם בעניינים ביטחוניים יש להחיל את מבחן הוודאות הקרובה לפגיעה ממשית בביטחון, ופסל את שיקול הדעת הרחב של הצנזור. ההלכה: חופש הביטוי נחשב זכות על גם בלי עיגון חוקתי, וגם בנושאי ביטחון.'),
box('case','אל-על נ׳ דנילוביץ (בג"ץ 721/94, 1994)','אל-על העניקה הטבות כרטיסי טיסה לבני זוג של עובדים, אך סירבה להעניק אותן לבן זוגו של דיילת-גבר שחי בזוגיות חד-מינית. בית המשפט קבע שזו הפליה אסורה. ההלכה: עקרון השוויון חל גם על מעסיקים והוא נגזר מעקרונות היסוד של השיטה, ולא נדרש עיגון חוקתי כדי להחילו.'),
h3('8.5 מצב החירום ותקנות ההגנה'),
p('אחד המאפיינים של התקופה שלפני המהפכה הוא מצב החירום שהוכרז ב-1948 ונמשך בהארכות חוזרות. מכוחו נשארו בתוקף תקנות שעת חירום רחבות, כולל תקנות ההגנה (שעת חירום) מ-1945, ומגבלות על חירויות. כאשר חוק היסוד: כבוד האדם נחקק, נקבע (ס׳ 12) שתקנות שעת חירום לא יפגעו בזכויות אלא לתכלית ראויה ובמידה שאינה עולה על הנדרש. המשמעות היא שהמהפכה צמצמה גם את כוחן של תקנות החירום, אף ששמירת הדינים המשיכה להגן על חלק מהדין הקיים.'),
box('warn','מלכודות נפוצות',['לטעון שלפני 1992 לא הוגנו זכויות כלל - הוגנו בפסיקה.','לטעון שמגילת העצמאות חוקה מחייבת - היא מקור פרשני בלבד.','להניח שבית המשפט יכל לפסול חוק פוגע לפני 1995 - בפועל פסל רק כשהכנסת לא עמדה בשריון (ברגמן).','לבלבל בין חזקה פרשנית (נגד פגיעה בזכות) לבין סמכות פסילה.']),
h3('8.6 שלד לפתרון שאלה'),
ol('זהה את הזכות ואת מקורה: חוק, פסיקה או חוק יסוד.','בדוק אם קיים חוק מפורש הפוגע בזכות.','אם כן - הפרשנות המקיימת אינה אפשרית; אם לא - החל חזקה פרשנית ופרש לטובת הזכות.','בדוק אם הרשות המבצעת פעלה בהסמכה ברורה.','ציין מה השתנה אחרי 1992.'),
box('ex','תרגיל פתור','שר סוגר עיתון בטענה שהוא מסית, בלי הסמכה מפורשת למקרה זה. <b>פתרון:</b> מדובר בהחלטה מנהלית. גם לפני 1992 יפרש בית המשפט את הסמכות בצמצום, וידרוש ודאות קרובה לפגיעה בשלום הציבור (קול העם). אין צורך בחוק יסוד כדי לפסול את ההחלטה.'),
box('key','סיכום הפרק',['לפני 1992: ללא עיגון חוקתי; הגנה פרשנית ושיפוטית.','מקורות: מגילת העצמאות, חקיקה, פסיקה.','קול העם, ברגמן, שניצר, דנילוביץ - תקדימים מוקדמים.','לא ניתן היה לפסול חוק מפורש, מלבד הפרת שריון.'])
]
CASES=[
('בג"ץ 73/53 חברת "קול העם" בע"מ נ׳ שר הפנים, פ"ד ז 871 (1953)','שר הפנים סגר שני עיתונים בטענה שהם מסכנים את שלום הציבור.','חופש הביטוי הוא יסוד הדמוקרטיה, וסמכות להגבילו נבחנת בצמצום; הוכרע מבחן הוודאות הקרובה לפגיעה ממשית. למבחן: דוגמה קלאסית להגנה על זכות בלתי כתובה דרך פרשנות.'),
('בג"ץ 98/69 ברגמן נ׳ שר האוצר (1969)','חוק מימון מפלגות נחקק ללא הרוב המשוריין לשוויון בבחירות.','החוק בטל; הכנסת כבולה בהוראת שריון. למבחן: הגבלה על הכנסת גם לפני המהפכה, אך מכוח שריון.'),
('בג"ץ 680/88 שניצר נ׳ הצנזור הצבאי הראשי (1989)','הצנזור פסל מאמר עיתונאי בנושא ביטחוני.','גם בנושאי ביטחון חל מבחן הוודאות הקרובה לפגיעה ממשית. למבחן: הרחבה של קול העם לתחום הביטחון.'),
('בג"ץ 721/94 אל-על נ׳ דנילוביץ, פ"ד מח(5) 749 (1994)','סירוב להעניק הטבות כרטיסי טיסה לבן זוג חד-מיני.','העיקרון: חובת שוויון חלה על מעסיקים. הפליה מטעמי נטייה מינית אסורה גם בלי עיגון בחוק יסוד. למבחן: שוויון כעיקרון יסוד.'),
('הכרזת העצמאות','המגילה הצהירה על שוויון, חופש דת, מצפון ושפה.','אין לה מעמד נורמטיבי מחייב, אך היא כלי פרשני. למבחן: שימוש בה כמקור השראה ולא כמקור לסמכות פסילה.')
]
QS=[
Q('מה היה מעמדן החוקתי של זכויות האדם בישראל לפני 1992?','לא היה עיגון חוקתי מפורש; ההגנה בפסיקה ובחקיקה רגילה',['עיגון מלא בחוקה פורמלית','עיגון בחוק יסוד: כבוד האדם','אין הגנה כלל'],'לפני 1992 לא היו חוקי זכויות. זכויות הוגנו בפסיקה ובחוקים בודדים. הקביעה שאין הגנה כלל שגויה, וחוקה פורמלית או חוק יסוד לא היו קיימים.'),
Q('איזה מקור משמש כלי פרשני לזכויות אך אינו מחייב?','מגילת העצמאות',['חוק יסוד: כבוד האדם','חוק העונשין','תקנות ההגנה'],'מגילת העצמאות היא מקור השראה ופרשנות ללא מעמד נורמטיבי מחייב. חוק כבוד האדם מאוחר ומחייב, ושני האחרים אינם מקורות פרשניים לזכויות.'),
Q('מהו מבחן הוודאות הקרובה?','הגבלת ביטוי רק כשיש ודאות קרובה לפגיעה ממשית בשלום הציבור',['הגבלת ביטוי בכל אפשרות סבירה לפגיעה','איסור מוחלט על הגבלת ביטוי','הגבלה רק בתקופת מלחמה'],'המבחן מחמיר מאוד עם הגבלות ומגן על הביטוי. אפשרות סבירה בלבד אינה מספקת, ואין איסור מוחלט, והמבחן אינו מוגבל למלחמה.'),
Q('מי כתב את פסק הדין בקול העם?','השופט אגרנט',['השופט ברק','השופט שמגר','השופט חשין'],'קול העם נכתב מפי השופט אגרנט (1953). ברק, שמגר וחשין שייכים לדור מאוחר ולפסקי דין כמו בנק המזרחי.'),
Q('מה עשה שר הפנים בפרשת קול העם?','סגר עיתונים בטענה לסכנה לשלום הציבור',['אסר על קיום בחירות','פיזר מפלגה','גירש עיתונאים'],'שר הפנים סגר את קול העם ואל-אתיחאד, ובית המשפט ביטל זאת. הסעיפים האחרים אינם העובדות בפרשה.'),
Q('מה הייתה המגבלה העיקרית של ההגנה השיפוטית לפני 1992?','אי היכולת לפסול חוק מפורש של הכנסת',['אי היכולת לפרש חוקים','אי היכולת לבקר את הממשלה','אי היכולת לדון בעתירות'],'בית המשפט פירש חוקים ובקר רשויות, אך לא יכל לפסול חוק מפורש. הטענות האחרות מתארות סמכויות שדווקא היו קיימות.'),
Q('מהי "חזקה פרשנית" בהקשר זכויות?','חזקה שהמחוקק לא התכוון לפגוע בזכות יסוד אלא אם אמר זאת במפורש',['חזקה שכל חוק פוגע בזכות','חזקה שהעותר צודק','חזקה שבג"ץ מחוקק'],'החזקה מובילה לפרשנות לטובת הזכות. חזקה שכל חוק פוגע בזכות, שהעותר צודק או שבג"ץ מחוקק אינן כללי פרשנות.'),
Q('בברגמן הוכרע ש:','חוק שלא נתקבל ברוב הנדרש לשריון בטל',['אין לבית המשפט סמכות לבקר חוק','חוק מימון מפלגות תקף','הכנסת רשאית לעקוף שריון'],'ברגמן ביטא כפיפות הכנסת לשריון. אי סמכות או תקפות החוק הפוכות.'),
Q('בשניצר נקבע כי הצנזור:','כפוף למבחן הוודאות הקרובה',['רשאי לפסול כל פרסום','אינו כפוף לביקורת','כפוף רק לממשלה'],'הצנזור כפוף למבחן הוודאות הקרובה גם בביטחון. שיקול דעת בלתי מוגבל אינו תקף.'),
Q('דנילוביץ עסק ב:','הפליה בהטבות כרטיסי טיסה לבן זוג חד-מיני',['חופש ביטוי','חופש עיסוק','קניין'],'זו פרשת שוויון ונטייה מינית אצל מעסיק. ביטוי, עיסוק וקניין אינם הנושא.'),
Q('איזה חוק משנת 1951 הגן על שוויון נשים?','חוק שוויון זכויות האישה',['חוק הגנת הפרטיות','חוק יסוד: הכנסת','חוק השבות'],'חוק שוויון זכויות האישה (1951) הגן על שוויון נשים. פרטיות היא חוק מ-1981, וחוק השבות עוסק בעלייה.'),
Q('מה משמעות "מגילת זכויות שיפוטית"?','הכרה בזכויות יסוד בפסיקה למרות היעדר חוקה',['מגילת זכויות בחוק יסוד','החלטת הממשלה בדבר זכויות','תקנון של לשכת עורכי הדין'],'המונח מתאר פיתוח זכויות בפסיקה. חוק יסוד או החלטת ממשלה אינם מקור שלה.'),
Q('מהן תקנות ההגנה (שעת חירום) מ-1945?','תקנות מנדטוריות שנשארו בתוקף וניתנו לשימוש בשעת חירום',['חוק יסוד','תקנות הכנסת','פסק דין'],'תקנות ההגנה הן דין מנדטורי שנשאר בתוקף. אינן חוק יסוד, תקנות הכנסת או פסק דין.'),
Q('מצב החירום בישראל הוכרז:','בשנת 1948 והוארך מעת לעת',['בשנת 1992','בשנת 2001 בלבד','מעולם לא הוכרז'],'מצב החירום הוכרז עם הקמת המדינה והוארך. 1992 היא שנת חוקי הזכויות, והטענה שלא הוכרז שגויה.'),
Q('מהו ס׳ 12 לחוק יסוד: כבוד האדם?','הגבלת תקנות שעת חירום פוגעות בזכויות',['שמירת דינים','פסקת התגברות','פסקת הגבלה'],'ס׳ 12 עוסק בתקנות שעת חירום. שמירת דינים היא ס׳ 10, והגבלה ס׳ 8, והתגברות אינה בחוק זה.'),
Q('מהי ההבדל בין לפני 1992 ואחריו בפגיעה בחוק מפורש?','לפני 1992 תקפה, אחרי 1992 תקפה רק אם עמדה בפסקת ההגבלה',['אין הבדל','לפני בטלה','אחרי תקפה תמיד'],'השינוי הוא עיקר המהפכה. בלי הבדל או בטלות מראש אינם נכונים.'),
Q('מה המשותף לפרשות קול העם ושניצר?','שתיהן יישמו את מבחן הוודאות הקרובה להגבלת חופש הביטוי',['שתיהן פסלו חוק של הכנסת','שתיהן עסקו בחופש העיסוק','שתיהן ניתנו לאחר המהפכה החוקתית'],'בשתי הפרשות נבחנה הגבלת ביטוי לפי מבחן הוודאות הקרובה, הראשונה בעיתונות והשנייה בצנזורה ביטחונית. אף אחת מהן לא פסלה חוק, והן ניתנו לפני 1992 ולכן אינן קשורות לחופש העיסוק.'),
Q('איזה עיקרון חל על מעסיק פרטי לפי דנילוביץ?','חובת שוויון',['חופש חוזים בלבד','שיקול דעת מוחלט','אי שוויון מותר'],'הפסיקה החילה שוויון גם על מעסיקים. חופש חוזים אינו מוחלט.'),
Q('למה נחשבת מגילת העצמאות "כלי פרשני"?','משום שהיא אינה חוק מחייב',['משום שהיא חוק יסוד','משום שהיא פסק דין','משום שהיא תקנה'],'כלי פרשני משמעו מקור להבנת הערכים. היא אינה חוק יסוד, פסק דין או תקנה.'),
Q('מה השתנה בנטל ההצדקה אחרי 1992?','הוא עבר לרשות הפוגעת בזכות',['הוא עבר לפרט','אין נטל','הוא עבר לבג"ץ'],'המדינה צריכה להצדיק פגיעה בזכות חוקתית. הפרט מוכיח פגיעה בלבד.'),
Q('איזה מבין הבאים אינו מקור להכרה בזכויות לפני 1992?','פסקת ההגבלה בחוק יסוד',['מגילת העצמאות','חקיקה רגילה','הפסיקה'],'פסקת ההגבלה נולדה ב-1992. שלושת האחרים הם המקורות.'),
]
